@extends('layouts.app')@section('content')<div class="page-head"><div><div class="eyebrow">PAYMENT FLOW</div><h1>Initiate Payment</h1><p>Card status and limits are validated server-side before gateway initiation.</p></div></div><div class="panel form-panel"><form method="POST" action="{{ route('payments.store') }}">@csrf<div class="form-grid"><label class="wide">Business<select id="business" name="business_id" required>@foreach($businesses as $b)<option value="{{ $b->id }}" data-cards='@json($b->cards)'>{{ $b->name }}</option>@endforeach</select></label><label>Virtual Card<select id="card" name="card_id" required></select></label><label>Amount (INR)<input name="amount" type="number" step="0.01" min="0.01" required></label><label>Gateway<select name="gateway"><option value="mock">Mock Sandbox</option><option value="razorpay">Razorpay</option><option value="paytm">Paytm</option></select></label></div><div class="notice">Flow: validate card → limits → create payment → gateway checkout → server verification/webhook → transaction ledger.</div><div class="form-actions"><a class="btn secondary" href="{{ route('payments.index') }}">Cancel</a><button class="btn primary">Create Payment</button></div></form></div><script>const b=document.querySelector('#business'),c=document.querySelector('#card');function sync(){const cards=JSON.parse(b.selectedOptions[0].dataset.cards||'[]');c.innerHTML=cards.map(x=>`<option value="${x.id}">${x.reference} · ${x.cardholder_name} · ₹${Number(x.current_usage).toFixed(2)} used</option>`).join('')}b.addEventListener('change',sync);sync();</script>@endsection
